import {WebGLRenderTarget,FloatType,RGFormat,NearestFilter,ShaderMaterial,Vector2,Vector4} from 'three';
import {FullScreenQuad} from 'three/addons/postprocessing/Pass.js';
import {depthHierarchyLayout} from './hierarchical-depth.js';
export class HierarchicalDepthPass{
 constructor(){this.levels=[];this.layout=null;this.atlas=null;this.material=new ShaderMaterial({uniforms:{source:{value:null},sourceSize:{value:new Vector2()},first:{value:1}},vertexShader:'void main(){gl_Position=vec4(position.xy,0,1);}',fragmentShader:'uniform sampler2D source;uniform vec2 sourceSize;uniform float first;void main(){ivec2 at=ivec2(gl_FragCoord.xy)*2,size=ivec2(sourceSize);vec2 range=vec2(1,0);for(int y=0;y<2;y++)for(int x=0;x<2;x++){vec2 v=texelFetch(source,min(at+ivec2(x,y),size-1),0).rg;if(first>.5)v=vec2(v.x);range=vec2(min(range.x,v.x),max(range.y,v.y));}gl_FragColor=vec4(range,0,1);}',depthTest:false,depthWrite:false,toneMapped:false});this.quad=new FullScreenQuad(this.material);}
 setSize(w,h){if(this.layout?.sourceWidth===w&&this.layout?.sourceHeight===h)return;this.release();this.layout={...depthHierarchyLayout(w,h),sourceWidth:w,sourceHeight:h};const options={type:FloatType,format:RGFormat,minFilter:NearestFilter,magFilter:NearestFilter,depthBuffer:false};this.atlas=new WebGLRenderTarget(this.layout.width,this.layout.height,options);this.levels=this.layout.levels.map(l=>new WebGLRenderTarget(l.width,l.height,options));}
 render(renderer,depth,w,h){this.setSize(w,h);const target=renderer.getRenderTarget(),viewport=renderer.getViewport(new Vector4()),scissor=renderer.getScissor(new Vector4()),scissorTest=renderer.getScissorTest(),u=this.material.uniforms;try{renderer.initRenderTarget(this.atlas);renderer.setScissorTest(false);let source=depth,size=[w,h];for(let i=0;i<this.levels.length;i++){const level=this.levels[i];u.source.value=source;u.sourceSize.value.fromArray(size);u.first.value=i===0?1:0;renderer.setRenderTarget(level);this.quad.render(renderer);renderer.copyTextureToTexture(level.texture,this.atlas.texture,null,new Vector2(0,this.layout.levels[i].y));source=level.texture;size=[level.width,level.height];}}finally{renderer.setRenderTarget(target);renderer.setViewport(viewport);renderer.setScissor(scissor);renderer.setScissorTest(scissorTest);}return this.atlas.texture;}
 release(){this.atlas?.dispose();for(const l of this.levels)l.dispose();this.atlas=null;this.levels=[];this.layout=null;}
 dispose(){this.release();this.material.dispose();this.quad.dispose();}
}
